import React from 'react';

function App() {
  const joinDiscord = () => {
    window.open('https://discord.gg/nwcrh7uG9y', '_blank');
  };
  return (
    <>
      <audio src="/audio/RobDougan-ClubbedToDeath.mp3" autoPlay loop />
      <div style={{
        minHeight: '100vh',
        background: '#23272a', // dark grey
        color: '#e0e0e0', // light grey text
        fontFamily: 'monospace',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        letterSpacing: 1,
        fontSize: 22
      }}>
        <div style={{
          background: '#2c2f33', // slightly lighter grey
          border: '2px solid #444',
          borderRadius: 8,
          padding: '40px 32px',
          boxShadow: '0 0 24px #2228',
          textAlign: 'center',
          maxWidth: 420
        }}>
          <div style={{ fontSize: 32, fontWeight: 'bold', marginBottom: 18, color: '#e0e0e0', textShadow: '0 0 8px #222' }}>
            Civ 5 Multiplayer No quit
          </div>
          <div style={{ fontSize: 18, marginBottom: 32, color: '#b0b0b0', textShadow: '0 0 4px #222' }}>
            Oldschool rules. No rage quitters. Just play.
          </div>
          <button
            onClick={joinDiscord}
            style={{
              background: '#36393f',
              color: '#e0e0e0',
              border: '2px solid #444',
              borderRadius: 6,
              fontFamily: 'monospace',
              fontSize: 20,
              padding: '12px 36px',
              cursor: 'pointer',
              boxShadow: '0 0 12px #2228',
              marginTop: 8,
              textTransform: 'uppercase',
              letterSpacing: 2,
              transition: 'background 0.2s, color 0.2s'
            }}
            onMouseOver={e => {
              e.target.style.background = '#444';
              e.target.style.color = '#fff';
            }}
            onMouseOut={e => {
              e.target.style.background = '#36393f';
              e.target.style.color = '#e0e0e0';
            }}
          >
            Join Discord
          </button>
        </div>
      </div>
    </>
  );
}

export default App;
